import json
import sys

# 模拟 name_map 数据
name_map = {
    "characters": {
        "10000002": {"cn_sim": "神里绫华", "cn_trad": "神里綾華", "en": "Kamisato Ayaka"},
        "10000073": {"cn_sim": "纳西妲", "cn_trad": "納西妲", "en": "Nahida"}
    },
    "weapons": {},
    "artifacts": {}
}

def find_id_by_name\(name_map, data_type, name, fuzzy=False\):
    if not name_map:
        return []

    type_map = name_map.get\("characters", {}\)
    matches = []
    search_name = name.lower\(\)

    for id_, names in type_map.items\(\):
        for name_field in ["cn_sim", "cn_trad", "en"]:
            if name_field in names:
                target_name = names[name_field].lower\(\)
                if fuzzy:
                    if search_name in target_name:
                        matches.append\(\(id_, names\)\)
                        break
                else:
                    if search_name == target_name:
                        return [\(id_, names\)]
    return matches

# 测试精确搜索
result = find_id_by_name\(name_map, "character", "纳西妲", fuzzy=False\)
