import json
import sys
from pathlib import Path

# 临时覆盖 NAME_MAP_FILE
NAME_MAP_FILE = Path\("/tmp/test_name_map.json"\)

def load_name_map\(\):
    try:
        with open\(NAME_MAP_FILE, "r", encoding="utf-8"\) as f:
            return json.load\(f\)
    except FileNotFoundError:
        print\(f"警告: 未找到名称映射文件 {NAME_MAP_FILE}", file=sys.stderr\)
        print\("提示: 请先运行 preprocess.py 生成映射文件", file=sys.stderr\)
        return None

def find_id_by_name\(name_map, data_type, name, fuzzy=False\):
    if not name_map:
        return []

    type_map = name_map.get\(data_type, {}\)
    matches = []
    search_name = name.lower\(\)

    for id_, names in type_map.items\(\):
        for name_field in ["cn_sim", "cn_trad", "en"]:
            if name_field in names:
                target_name = names[name_field].lower\(\)
                if fuzzy:
                    if search_name in target_name:
                        matches.append\(\(id_, names\)\)
                        break
                else:
                    if search_name == target_name:
                        return [\(id_, names\)]
    return matches

# 测试
name_map = load_name_map\(\)
print\(f"加载映射文件: {name_map is not None}"\)

# 精确搜索
